Ok now make sure it still matches this embedded 4d base. <!DOCTYPE html>

<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>RDSC Lattice — 4D Hypercube</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Space+Mono:ital,wght@0,400;0,700;1,400&family=Syne:wght@400;600;700;800&display=swap');

:root {
–bg: #080a0f;
–surface: #0d1117;
–border: #1c2333;
–text: #c9d1d9;
–dim: #58627a;
–accent-R: #ff6b35;
–accent-D: #38bdf8;
–accent-S: #a78bfa;
–accent-C: #34d399;
–diagonal: #fbbf24;
–glow-R: rgba(255,107,53,0.15);
–glow-D: rgba(56,189,248,0.15);
–glow-S: rgba(167,139,250,0.15);
–glow-C: rgba(52,211,153,0.15);
}

- { box-sizing: border-box; margin: 0; padding: 0; }

body {
background: var(–bg);
color: var(–text);
font-family: ‘Space Mono’, monospace;
min-height: 100vh;
overflow-x: hidden;
}

/* Grain overlay */
body::before {
content: ‘’;
position: fixed;
inset: 0;
background-image: url(“data:image/svg+xml,%3Csvg viewBox=‘0 0 256 256’ xmlns=‘http://www.w3.org/2000/svg’%3E%3Cfilter id=‘noise’%3E%3CfeTurbulence type=‘fractalNoise’ baseFrequency=‘0.9’ numOctaves=‘4’ stitchTiles=‘stitch’/%3E%3C/filter%3E%3Crect width=‘100%25’ height=‘100%25’ filter=‘url(%23noise)’ opacity=‘0.03’/%3E%3C/svg%3E”);
pointer-events: none;
z-index: 1000;
opacity: 0.4;
}

header {
padding: 2rem 3rem 1.5rem;
border-bottom: 1px solid var(–border);
display: flex;
align-items: flex-end;
justify-content: space-between;
gap: 2rem;
}

.logo {
font-family: ‘Syne’, sans-serif;
font-weight: 800;
font-size: 2rem;
letter-spacing: -0.04em;
color: #fff;
}
.logo span { color: var(–diagonal); }

.subtitle {
font-size: 0.65rem;
color: var(–dim);
letter-spacing: 0.15em;
text-transform: uppercase;
margin-top: 0.3rem;
}

.dim-pills {
display: flex;
gap: 0.5rem;
flex-wrap: wrap;
}

.pill {
font-size: 0.6rem;
letter-spacing: 0.1em;
text-transform: uppercase;
padding: 0.25rem 0.6rem;
border-radius: 2px;
font-weight: 700;
}
.pill-R { background: rgba(255,107,53,0.12); color: var(–accent-R); border: 1px solid rgba(255,107,53,0.3); }
.pill-D { background: rgba(56,189,248,0.12); color: var(–accent-D); border: 1px solid rgba(56,189,248,0.3); }
.pill-S { background: rgba(167,139,250,0.12); color: var(–accent-S); border: 1px solid rgba(167,139,250,0.3); }
.pill-C { background: rgba(52,211,153,0.12); color: var(–accent-C); border: 1px solid rgba(52,211,153,0.3); }

.layout {
display: grid;
grid-template-columns: 1fr 340px;
min-height: calc(100vh - 90px);
}

/* –– LEFT: lattice grid –– */
.lattice-panel {
padding: 2rem 3rem;
border-right: 1px solid var(–border);
overflow-y: auto;
}

.section-label {
font-size: 0.6rem;
letter-spacing: 0.2em;
text-transform: uppercase;
color: var(–dim);
margin-bottom: 1.5rem;
display: flex;
align-items: center;
gap: 0.75rem;
}
.section-label::after {
content: ‘’;
flex: 1;
height: 1px;
background: var(–border);
}

.filter-row {
display: flex;
gap: 0.5rem;
margin-bottom: 1.5rem;
flex-wrap: wrap;
}

.filter-btn {
font-family: ‘Space Mono’, monospace;
font-size: 0.6rem;
letter-spacing: 0.1em;
text-transform: uppercase;
padding: 0.3rem 0.75rem;
border-radius: 2px;
background: transparent;
border: 1px solid var(–border);
color: var(–dim);
cursor: pointer;
transition: all 0.15s;
}
.filter-btn:hover { border-color: var(–text); color: var(–text); }
.filter-btn.active { background: rgba(251,191,36,0.1); border-color: var(–diagonal); color: var(–diagonal); }

.lattice-grid {
display: grid;
grid-template-columns: repeat(4, 1fr);
gap: 0.5rem;
}

.node {
position: relative;
padding: 0.85rem;
background: var(–surface);
border: 1px solid var(–border);
border-radius: 3px;
cursor: pointer;
transition: all 0.18s;
animation: fadeIn 0.4s ease both;
}

@keyframes fadeIn {
from { opacity: 0; transform: translateY(6px); }
to { opacity: 1; transform: translateY(0); }
}

.node:hover {
border-color: rgba(201,209,217,0.3);
transform: translateY(-2px);
z-index: 10;
}
.node.selected {
border-color: var(–diagonal);
box-shadow: 0 0 0 1px var(–diagonal), 0 0 20px rgba(251,191,36,0.1);
}
.node.diagonal {
border-color: rgba(251,191,36,0.25);
}
.node.diagonal::before {
content: ‘’;
position: absolute;
inset: 0;
background: radial-gradient(ellipse at top left, rgba(251,191,36,0.06), transparent 60%);
border-radius: 2px;
pointer-events: none;
}
.node.dimmed { opacity: 0.25; }

.node-address {
font-size: 0.95rem;
font-weight: 700;
letter-spacing: 0.05em;
margin-bottom: 0.4rem;
display: flex;
align-items: center;
gap: 0.3rem;
}

.bit {
display: inline-block;
width: 0.9rem;
text-align: center;
border-radius: 2px;
padding: 0 1px;
}
.bit-R-1 { color: var(–accent-R); }
.bit-D-1 { color: var(–accent-D); }
.bit-S-1 { color: var(–accent-S); }
.bit-C-1 { color: var(–accent-C); }
.bit-0 { color: #2d3748; }

.node-archetype {
font-size: 0.6rem;
color: var(–text);
line-height: 1.45;
margin-bottom: 0.35rem;
display: -webkit-box;
-webkit-line-clamp: 2;
-webkit-box-orient: vertical;
overflow: hidden;
}

.node-tags {
display: flex;
gap: 0.25rem;
flex-wrap: wrap;
margin-top: 0.4rem;
}

.tag {
font-size: 0.5rem;
padding: 0.1rem 0.3rem;
border-radius: 1px;
letter-spacing: 0.05em;
text-transform: uppercase;
}
.tag-R { background: rgba(255,107,53,0.08); color: var(–accent-R); }
.tag-D { background: rgba(56,189,248,0.08); color: var(–accent-D); }
.tag-S { background: rgba(167,139,250,0.08); color: var(–accent-S); }
.tag-C { background: rgba(52,211,153,0.08); color: var(–accent-C); }
.tag-diagonal { background: rgba(251,191,36,0.08); color: var(–diagonal); }

/* –– RIGHT: detail panel –– */
.detail-panel {
padding: 2rem;
display: flex;
flex-direction: column;
gap: 1.5rem;
overflow-y: auto;
}

.detail-empty {
color: var(–dim);
font-size: 0.65rem;
letter-spacing: 0.1em;
text-align: center;
margin-top: 4rem;
line-height: 2;
}

.detail-address {
font-family: ‘Syne’, sans-serif;
font-size: 3rem;
font-weight: 800;
letter-spacing: -0.04em;
line-height: 1;
color: #fff;
}

.detail-dim-bar {
display: grid;
grid-template-columns: 1fr 1fr;
gap: 0.5rem;
margin-top: 0.75rem;
}

.dim-cell {
padding: 0.6rem 0.75rem;
border-radius: 2px;
border: 1px solid;
}
.dim-cell-label {
font-size: 0.55rem;
letter-spacing: 0.12em;
text-transform: uppercase;
opacity: 0.7;
margin-bottom: 0.2rem;
}
.dim-cell-value {
font-size: 0.7rem;
font-weight: 700;
}

.detail-archetype {
font-family: ‘Syne’, sans-serif;
font-size: 1rem;
font-weight: 600;
color: #fff;
line-height: 1.4;
}

.detail-examples {
background: rgba(255,255,255,0.02);
border: 1px solid var(–border);
border-radius: 3px;
padding: 1rem;
}
.detail-examples-label {
font-size: 0.55rem;
letter-spacing: 0.15em;
text-transform: uppercase;
color: var(–dim);
margin-bottom: 0.6rem;
}
.detail-examples-text {
font-size: 0.65rem;
line-height: 1.8;
color: var(–text);
}
.detail-examples-text .ex-item::before {
content: ’→ ’;
color: var(–dim);
}

.detail-dimensions {
display: flex;
flex-direction: column;
gap: 0.4rem;
}

.dim-row {
display: flex;
align-items: center;
gap: 0.75rem;
padding: 0.5rem 0.6rem;
border-radius: 2px;
border: 1px solid var(–border);
}
.dim-row-letter {
font-weight: 700;
font-size: 0.8rem;
width: 1rem;
text-align: center;
}
.dim-row-name {
font-size: 0.58rem;
color: var(–dim);
text-transform: uppercase;
letter-spacing: 0.08em;
flex: 1;
}
.dim-row-state {
font-size: 0.6rem;
font-weight: 700;
text-align: right;
}

.diagonal-badge {
display: inline-flex;
align-items: center;
gap: 0.4rem;
font-size: 0.6rem;
color: var(–diagonal);
background: rgba(251,191,36,0.08);
border: 1px solid rgba(251,191,36,0.25);
padding: 0.35rem 0.7rem;
border-radius: 2px;
letter-spacing: 0.08em;
}

/* path visualizer */
.path-section {
border-top: 1px solid var(–border);
padding-top: 1.5rem;
}
.path-label {
font-size: 0.55rem;
letter-spacing: 0.15em;
text-transform: uppercase;
color: var(–dim);
margin-bottom: 0.75rem;
}
.path-nodes {
display: flex;
gap: 0.25rem;
flex-wrap: wrap;
align-items: center;
}
.path-node {
font-size: 0.65rem;
padding: 0.2rem 0.45rem;
border: 1px solid var(–border);
border-radius: 2px;
cursor: pointer;
transition: all 0.15s;
color: var(–dim);
}
.path-node:hover { color: var(–text); border-color: var(–text); }
.path-node.path-current { color: var(–diagonal); border-color: var(–diagonal); }
.path-arrow { color: var(–border); font-size: 0.6rem; }

/* Hamming neighbors */
.neighbors-grid {
display: flex;
gap: 0.3rem;
flex-wrap: wrap;
}
.neighbor-chip {
font-size: 0.6rem;
padding: 0.2rem 0.5rem;
border: 1px solid var(–border);
border-radius: 2px;
cursor: pointer;
color: var(–dim);
transition: all 0.15s;
font-weight: 700;
}
.neighbor-chip:hover { border-color: var(–text); color: var(–text); }

.scrollbar-thin::-webkit-scrollbar { width: 4px; }
.scrollbar-thin::-webkit-scrollbar-track { background: transparent; }
.scrollbar-thin::-webkit-scrollbar-thumb { background: var(–border); border-radius: 2px; }
</style>

</head>
<body>

<header>
  <div>
    <div class="logo">RDSC <span>Lattice</span></div>
    <div class="subtitle">4-Dimensional Hypercube · 16 Vertices · 4 Axes</div>
  </div>
  <div class="dim-pills">
    <div class="pill pill-R">R — Reality</div>
    <div class="pill pill-D">D — Design</div>
    <div class="pill pill-S">S — System</div>
    <div class="pill pill-C">C — Cognition</div>
  </div>
</header>

<div class="layout">
  <div class="lattice-panel scrollbar-thin">
    <div class="section-label">All 16 vertices</div>
    <div class="filter-row" id="filterRow"></div>
    <div class="lattice-grid" id="latticeGrid"></div>
  </div>
  <div class="detail-panel scrollbar-thin" id="detailPanel">
    <div class="detail-empty">← Select a vertex<br>to explore its archetype,<br>neighbors, and axes</div>
  </div>
</div>

<script>
const DIMS = [
  { key: 'R', name: 'Reality', color: 'var(--accent-R)', 
    states: ['Classical / Chaotic / Local Gauge', 'Quantum / Intent / Emergent'] },
  { key: 'D', name: 'Design', color: 'var(--accent-D)', 
    states: ['Local Spec / ISA / Black Box', 'Shared Mental Model / Intent Interpreter'] },
  { key: 'S', name: 'System', color: 'var(--accent-S)', 
    states: ['Merkle Roots / Blockchain / Local', 'Team Consensus / History Trees / Global'] },
  { key: 'C', name: 'Cognition', color: 'var(--accent-C)', 
    states: ['Axioms / Decoherence / Low Human Levels', 'Proof-Carrying / Unitary / High Human Levels'] },
];

const NODES = [
  { id:'0000', R:0,D:0,S:0,C:0, archetype:'Pure classical, local design, local system, low cognition', examples:['Bare-metal firmware','Microcontroller without OS','BIOS','Embedded systems'], diagonal:true, level:'Level 0' },
  { id:'0001', R:0,D:0,S:0,C:1, archetype:'Classical, local design, local system, high cognition', examples:['COBOL mainframe apps','Single-user Lisp machine','Vintage Macintosh with advanced GUI'], diagonal:false },
  { id:'0010', R:0,D:0,S:1,C:0, archetype:'Classical, local design, distributed system, low cognition', examples:['Early Hadoop clusters','Cassandra on physical nodes','Raw distributed filesystems'], diagonal:false },
  { id:'0011', R:0,D:0,S:1,C:1, archetype:'Classical, local design, distributed, high cognition', examples:['Google Spanner','Amazon S3 with abstraction layer','High-consistency cloud storage'], diagonal:false },
  { id:'0100', R:0,D:1,S:0,C:0, archetype:'Classical, shared design, local system, low cognition', examples:['Spacecraft firmware teams','Shared embedded system dev with no abstraction'], diagonal:false },
  { id:'0101', R:0,D:1,S:0,C:1, archetype:'Classical, shared design, local, high cognition', examples:['Weather modeling teams','Financial risk simulation platforms','High-level classical simulation'], diagonal:false },
  { id:'0110', R:0,D:1,S:1,C:0, archetype:'Classical, shared design, distributed, low cognition', examples:['Custom Paxos on bare metal','Early Google infrastructure','Consensus without abstraction'], diagonal:false },
  { id:'0111', R:0,D:1,S:1,C:1, archetype:'Classical, shared design, distributed, high cognition', examples:['Kubernetes','Netflix microservices','Cloud-native platforms with strong coordination'], diagonal:true, level:'Level 4' },
  { id:'1000', R:1,D:0,S:0,C:0, archetype:'Quantum, local design, local, low cognition', examples:['IBM Quantum control electronics','Quantum hardware control firmware'], diagonal:false },
  { id:'1001', R:1,D:0,S:0,C:1, archetype:'Quantum, local design, local, high cognition', examples:['Qiskit','Cirq','Quantum algorithm libraries on single QPU'], diagonal:false },
  { id:'1010', R:1,D:0,S:1,C:0, archetype:'Quantum, local design, distributed, low cognition', examples:['QKD link layer protocols','Quantum repeater control','Minimal-abstraction quantum networks'], diagonal:false },
  { id:'1011', R:1,D:0,S:1,C:1, archetype:'Quantum, local design, distributed, high cognition', examples:['Gate teleportation algorithms','High-level entanglement distribution protocols'], diagonal:false },
  { id:'1100', R:1,D:1,S:0,C:0, archetype:'Quantum, shared design, local, low cognition', examples:['Lab research collaboration on quantum hardware','Low-level QPU team builds'], diagonal:false },
  { id:'1101', R:1,D:1,S:0,C:1, archetype:'Quantum, shared design, local, high cognition', examples:['Multi-user quantum programming platforms','Collaborative quantum algorithm IDEs'], diagonal:false },
  { id:'1110', R:1,D:1,S:1,C:0, archetype:'Quantum, shared design, distributed, low cognition', examples:['Quantum repeater networks','QKD infrastructure','Low-level quantum mesh'], diagonal:false },
  { id:'1111', R:1,D:1,S:1,C:1, archetype:'Quantum, shared design, distributed, high cognition', examples:['Global quantum internet','Distributed quantum computing','Quantum blockchain','Full abstraction stack'], diagonal:true, level:'Peak' },
];

// Diagonal path
const DIAGONAL_PATH = ['0000','0001','0011','0111','1111'];
// More complete diagonal approximation
const FULL_DIAGONAL = ['0000','0001','0011','0111','1111'];

let selectedId = null;
let activeFilter = null;

function hammingNeighbors(id) {
  return NODES.filter(n => {
    let diff = 0;
    for (let i = 0; i < 4; i++) diff += (n.id[i] !== id[i]) ? 1 : 0;
    return diff === 1;
  }).map(n => n.id);
}

function renderBits(id) {
  const labels = ['R','D','S','C'];
  return id.split('').map((b,i) => {
    const cls = b === '1' ? `bit bit-${labels[i]}-1` : 'bit bit-0';
    return `<span class="${cls}">${b}</span>`;
  }).join('');
}

function renderGrid() {
  const grid = document.getElementById('latticeGrid');
  grid.innerHTML = '';
  NODES.forEach((node, idx) => {
    const isSelected = node.id === selectedId;
    const neighbors = selectedId ? hammingNeighbors(selectedId) : [];
    const isDimmed = selectedId && !isSelected && !neighbors.includes(node.id);
    const dims = ['R','D','S','C'];
    const activeDim = activeFilter;
    const matchesFilter = !activeDim || node[activeDim] === 1;

    const el = document.createElement('div');
    el.className = [
      'node',
      isSelected ? 'selected' : '',
      node.diagonal ? 'diagonal' : '',
      isDimmed ? 'dimmed' : '',
      !matchesFilter && activeFilter ? 'dimmed' : ''
    ].filter(Boolean).join(' ');
    el.style.animationDelay = `${idx * 0.025}s`;

    const tags = dims.filter(d => node[d] === 1).map(d => `<span class="tag tag-${d}">${d}</span>`).join('');
    const diagonalTag = node.diagonal ? `<span class="tag tag-diagonal">${node.level || 'Diag'}</span>` : '';

    el.innerHTML = `
      <div class="node-address">${renderBits(node.id)}</div>
      <div class="node-archetype">${node.archetype}</div>
      <div class="node-tags">${diagonalTag}${tags}</div>
    `;
    el.addEventListener('click', () => selectNode(node.id));
    grid.appendChild(el);
  });
}

function renderDetail(id) {
  const panel = document.getElementById('detailPanel');
  if (!id) {
    panel.innerHTML = '<div class="detail-empty">← Select a vertex<br>to explore its archetype,<br>neighbors, and axes</div>';
    return;
  }
  const node = NODES.find(n => n.id === id);
  const neighbors = hammingNeighbors(id);
  const dimLabels = ['R','D','S','C'];

  const dimCells = DIMS.map((dim, i) => {
    const val = node[dim.key];
    const border = val ? `border-color: ${dim.color}30` : `border-color: var(--border)`;
    const bg = val ? `background: ${dim.color}08` : '';
    return `
      <div class="dim-cell" style="${border}; ${bg}">
        <div class="dim-cell-label" style="color:${val ? dim.color : 'var(--dim)'}">${dim.key} — ${dim.name}</div>
        <div class="dim-cell-value" style="color:${val ? dim.color : 'var(--dim)'}; font-size:0.6rem">${dim.states[val]}</div>
      </div>`;
  }).join('');

  const exItems = node.examples.map(e => `<div class="ex-item">${e}</div>`).join('');

  const neighborChips = neighbors.map(nid => {
    return `<span class="neighbor-chip" onclick="selectNode('${nid}')">${nid}</span>`;
  }).join('');

  const pathNodes = FULL_DIAGONAL.map((pid, i) => {
    const isCurrent = pid === id;
    const arrow = i < FULL_DIAGONAL.length - 1 ? '<span class="path-arrow">→</span>' : '';
    return `<span class="path-node ${isCurrent ? 'path-current' : ''}" onclick="selectNode('${pid}')">${pid}</span>${arrow}`;
  }).join('');

  const diagonalBadge = node.diagonal
    ? `<div class="diagonal-badge">⬡ Diagonal Path — ${node.level}</div>`
    : '';

  panel.innerHTML = `
    <div>
      <div class="detail-address">${renderBits(id)}</div>
      <div style="margin-top:0.5rem">${diagonalBadge}</div>
    </div>
    <div class="detail-dim-bar">${dimCells}</div>
    <div>
      <div class="detail-examples-label" style="font-family:Space Mono; font-size:0.55rem; letter-spacing:0.12em; text-transform:uppercase; color:var(--dim); margin-bottom:0.4rem">Archetype</div>
      <div class="detail-archetype">${node.archetype}</div>
    </div>
    <div class="detail-examples">
      <div class="detail-examples-label">Concrete examples</div>
      <div class="detail-examples-text">${exItems}</div>
    </div>
    <div>
      <div class="detail-examples-label" style="font-family:Space Mono; font-size:0.55rem; letter-spacing:0.12em; text-transform:uppercase; color:var(--dim); margin-bottom:0.5rem">Hamming-1 Neighbors (1-bit flips)</div>
      <div class="neighbors-grid">${neighborChips}</div>
    </div>
    <div class="path-section">
      <div class="path-label">Diagonal path (human levels)</div>
      <div class="path-nodes">${pathNodes}</div>
    </div>
  `;
}

function selectNode(id) {
  selectedId = selectedId === id ? null : id;
  renderGrid();
  renderDetail(selectedId);
}

function renderFilters() {
  const row = document.getElementById('filterRow');
  const allBtn = document.createElement('button');
  allBtn.className = 'filter-btn ' + (!activeFilter ? 'active' : '');
  allBtn.textContent = 'All';
  allBtn.onclick = () => { activeFilter = null; renderFilters(); renderGrid(); };
  row.appendChild(allBtn);

  DIMS.forEach(dim => {
    const btn = document.createElement('button');
    btn.className = 'filter-btn ' + (activeFilter === dim.key ? 'active' : '');
    btn.textContent = `${dim.key}=1 (${dim.name})`;
    btn.style.setProperty('--filter-color', dim.color);
    btn.onclick = () => {
      activeFilter = activeFilter === dim.key ? null : dim.key;
      renderFilters();
      renderGrid();
    };
    row.appendChild(btn);
  });

  const diagBtn = document.createElement('button');
  diagBtn.className = 'filter-btn ' + (activeFilter === 'diagonal' ? 'active' : '');
  diagBtn.textContent = 'Diagonal only';
  diagBtn.onclick = () => {
    activeFilter = activeFilter === 'diagonal' ? null : 'diagonal';
    renderFilters();
    renderGrid();
  };
  row.appendChild(diagBtn);
}

// Override renderGrid to handle diagonal filter
const _orig = renderGrid;
window.renderGrid = function() {
  const grid = document.getElementById('latticeGrid');
  grid.innerHTML = '';
  NODES.forEach((node, idx) => {
    const isSelected = node.id === selectedId;
    const neighbors = selectedId ? hammingNeighbors(selectedId) : [];
    const isDimmedBySelect = selectedId && !isSelected && !neighbors.includes(node.id);

    let isDimmedByFilter = false;
    if (activeFilter === 'diagonal') isDimmedByFilter = !node.diagonal;
    else if (activeFilter) isDimmedByFilter = node[activeFilter] !== 1;

    const el = document.createElement('div');
    el.className = [
      'node',
      isSelected ? 'selected' : '',
      node.diagonal ? 'diagonal' : '',
      (isDimmedBySelect || isDimmedByFilter) ? 'dimmed' : '',
    ].filter(Boolean).join(' ');
    el.style.animationDelay = `${idx * 0.025}s`;

    const dims = ['R','D','S','C'];
    const tags = dims.filter(d => node[d] === 1).map(d => `<span class="tag tag-${d}">${d}</span>`).join('');
    const diagonalTag = node.diagonal ? `<span class="tag tag-diagonal">${node.level || 'Diag'}</span>` : '';

    el.innerHTML = `
      <div class="node-address">${renderBits(node.id)}</div>
      <div class="node-archetype">${node.archetype}</div>
      <div class="node-tags">${diagonalTag}${tags}</div>
    `;
    el.addEventListener('click', () => selectNode(node.id));
    grid.appendChild(el);
  });
};

renderFilters();
renderGrid();
</script>

