  {bits:'1100', label:'Quantum hardware team'},
  {bits:'1101', label:'Collaborative quantum algorithms'},
  {bits:'1110', label:'Distributed quantum network'},
  {bits:'1111', label:'Global quantum internet'}
];

const RUNTIME_BITS = 12;
const MAX_HAMMING_DEVICE = 4; // devices with Hamming <=4 are considered legal

// Constraint DAG
function isValid(vertex) {
  const v = vertex.split('').map(Number);
  const coreSum = v.slice(0,4).reduce((a,b)=>a+b,0);
  const boot = v[6], trust=v[7], fault=v[11], evolution=v[14];
  return (boot===0 || coreSum>=1) &&
         (trust===0 || boot===1) &&
         (evolution===0 || trust===1) &&
         (fault===0 || boot===1);
}

// Generate runtime fibers for a given core (all 2^12 combinations, filtered)
function generateFiber(coreBits) {
  const fibers = [];
  const max = 1 << RUNTIME_BITS;
  for(let i=0;i<max;i++){
    let runtimeBits = i.toString(2).padStart(RUNTIME_BITS,'0');
    let vertex = coreBits + runtimeBits;
    if(isValid(vertex)) fibers.push(vertex);
  }
  return fibers;
}

// Hamming distance
function hamming(a,b) {
  let count=0;
  for(let i=0;i<a.length;i++) if(a[i]!==b[i]) count++;
  return count;
}

// Simple interaction policy (used in compare)
function canInteract(a,b) {
  const va = a.split('').map(Number);
  const vb = b.split('').map(Number);
  // Trust must match or both verified
  if (va[7] !== vb[7] && (va[7]===0 || vb[7]===0)) return false;
  // Both must be booted if network used (bit 8)
  if (va[8]===1 || vb[8]===1) {
    if (va[6]!==1 || vb[6]!==1) return false;
  }
  return true;
}

// ---------------------------
// Global state
// ---------------------------
let svg;
let width=1200,height=800;
let coreX, coreY;
let nodePositions = {}; // maps vertex id -> {x,y}
let selectedVertex = null;
let devices = []; // {vertex, x, y, element}

// ---------------------------
// Initialize SVG
// ---------------------------
function initSVG() {
  d3.select("#lattice").selectAll("*").remove();
  svg = d3.select("#lattice").append("svg")
    .attr("width", width)
    .attr("height", height);

  coreX = d3.scaleLinear().domain([0,3]).range([150, width-150]);
  coreY = d3.scaleLinear().domain([0,3]).range([150, height-150]);

  // Draw core vertices
  CORE_VERTICES.forEach((v,i)=>{
    const x = coreX(i%4);
    const y = coreY(Math.floor(i/4));
    nodePositions[v.bits] = {x,y};
    svg.append("circle")
      .attr("class","vertex")
      .attr("cx",x).attr("cy",y)
      .attr("r",12)
      .attr("data-id",v.bits)
      .on("click", (event) => selectVertex(event, v.bits))
      .append("title")
      .text(`${v.bits}: ${v.label}`);
  });
}

// ---------------------------
// Vertex selection
// ---------------------------
function selectVertex(event, bits) {
  // Clear previous selection highlight
  svg.selectAll(".selected").classed("selected",false);
  d3.select(event.target).classed("selected",true);
  selectedVertex = bits;

  // Remove old Hamming-1 edges if any
  svg.selectAll(".hamming-edge").remove();

  if (document.getElementById('showHammingEdges').checked) {
    // Draw legal Hamming-1 edges from this vertex
    const neighbors = findHamming1Legal(bits);
    neighbors.forEach(n => {
      const target = n.bits;
      if (nodePositions[target]) {
        svg.append("line")
          .attr("class","hamming-edge")
          .attr("x1", nodePositions[bits].x)
          .attr("y1", nodePositions[bits].y)
          .attr("x2", nodePositions[target].x)
          .attr("y2", nodePositions[target].y);
      }
    });
  }

  // Expand fibers for core vertices (if not already expanded)
  if (bits.length === 4) {
    expandFiber(bits);
  }
}

// Find all legal Hamming-1 neighbors (both core and runtime)
function findHamming1Legal(sourceBits) {
  const neighbors = [];
  for(let i=0;i<16;i++){
    let flipped = sourceBits.split('');
    flipped[i] = flipped[i]==='0'?'1':'0';
    let candidate = flipped.join('');
    if(isValid(candidate)) neighbors.push({bits:candidate, diffBit:i});
  }
  return neighbors;
}

// ---------------------------
// Fiber expansion
// ---------------------------
let expandedCore = null;
function expandFiber(coreBits) {
  // If same core already expanded, do nothing
  if (expandedCore === coreBits) return;
  expandedCore = coreBits;

  // Remove old fibers
  svg.selectAll(".fiber").remove();

  const fibers = generateFiber(coreBits);
  const angleStep = 2*Math.PI / Math.min(fibers.length, 120); // limit for performance
  const radius = 80;
  fibers.slice(0,120).forEach((f,i)=>{
    const angle = i*angleStep;
    const x = nodePositions[coreBits].x + radius*Math.cos(angle);
    const y = nodePositions[coreBits].y + radius*Math.sin(angle);
    nodePositions[f] = {x,y};
    svg.append("circle")
      .attr("class","vertex fiber")
      .attr("cx",x).attr("cy",y)
      .attr("r",4)
      .attr("data-id",f)
      .on("click", (event) => {
        // Click on fiber: either select or assign device (shift+click)
        if (event.shiftKey) {
          assignDevice(f, x, y);
        } else {
          selectVertex(event, f);
        }
      })
      .append("title").text(f);
  });
}

// ---------------------------
// Device management
// ---------------------------
function assignDevice(vertex, x, y) {
  // Avoid duplicates
  if (devices.find(d => d.vertex === vertex)) return;
  const el = svg.append("circle")
    .attr("class","vertex device")
    .attr("cx",x).attr("cy",y)
    .attr("r",7)
    .on("click", (event) => selectVertex(event, vertex))
    .append("title").text(`Device: ${vertex}`);
  devices.push({vertex, x, y, element: el});
  updateDeviceEdges();
}

function clearDevices() {
  devices.forEach(d => d.element.remove());
  devices = [];
  svg.selectAll(".edge").remove(); // also remove all edges
}

function updateDeviceEdges() {
  if (!document.getElementById('showDeviceEdges').checked) return;
  svg.selectAll(".edge").remove();
  for(let i=0;i<devices.length;i++) {
    for(let j=i+1;j<devices.length;j++) {
      const a = devices[i], b = devices[j];
      const dist = hamming(a.vertex, b.vertex);
      const legal = dist <= MAX_HAMMING_DEVICE;
      svg.append("line")
        .attr("class", legal ? "edge legal" : "edge illegal")
        .attr("x1", a.x).attr("y1", a.y)
        .attr("x2", b.x).attr("y2", b.y)
        .append("title")
        .text(`Hamming=${dist} ${legal ? 'legal' : 'illegal'}`);
    }
  }
}

// ---------------------------
// Compare two devices from input fields
// ---------------------------
function compareDevices() {
  const a = document.getElementById('deviceA').value.trim();
  const b = document.getElementById('deviceB').value.trim();
  if(a.length!==16 || b.length!==16){
    alert("Please enter 16-bit vertex IDs");
    return;
  }
  if(!isValid(a) || !isValid(b)) {
    alert("One or both vertices are invalid per DAG constraints");
    return;
  }
  const dist = hamming(a,b);
  const interact = canInteract(a,b) ? "✅ allowed" : "❌ blocked";
  document.getElementById('comparisonResult').innerHTML =
    `Hamming distance: ${dist} | Interaction: ${interact}`;
}

// ---------------------------
// Redraw based on checkbox toggles
// ---------------------------
function applyVisibility() {
  // Show/hide fibers
  const showFibers = document.getElementById('showFibers').checked;
  svg.selectAll(".fiber").style("display", showFibers ? null : "none");

  // Show/hide device edges
  const showDeviceEdges = document.getElementById('showDeviceEdges').checked;
  if (showDeviceEdges) updateDeviceEdges(); else svg.selectAll(".edge").remove();

  // Show/hide Hamming-1 edges
  const showHamming = document.getElementById('showHammingEdges').checked;
  svg.selectAll(".hamming-edge").style("display", showHamming ? null : "none");
  // If there's a selected vertex and we need to redraw Hamming edges
  if (showHamming && selectedVertex) {
    // trigger redraw? edges already exist; but if they were removed, we need to recreate
    // simple: if hamming edges missing, recreate them
    if (svg.selectAll(".hamming-edge").empty() && selectedVertex) {
      const neighbors = findHamming1Legal(selectedVertex);
      neighbors.forEach(n => {
        const target = n.bits;
        if (nodePositions[target]) {
          svg.append("line")
            .attr("class","hamming-edge")
            .attr("x1", nodePositions[selectedVertex].x)
            .attr("y1", nodePositions[selectedVertex].y)
            .attr("x2", nodePositions[target].x)
            .attr("y2", nodePositions[target].y);
        }
      });
    }
  } else {
    svg.selectAll(".hamming-edge").remove();
  }
}

