function createVertexMesh(vertexID, state){
    const core = vertexID.slice(0,4);
    const runtime = vertexID.slice(4);
    const decay = state.decay;
    const entropy = state.entropy;
    const trust = (vertexID[7]=='1')?1:0;
    const evolution = (vertexID[14]=='1')?1:0;

    // Position: X=Core R, Y=Core D, Z=Core S + runtime sum influence
    const x = parseInt(core[0],2)*50 + runtimeWeighted(runtime,0);
    const y = parseInt(core[1],2)*50 + runtimeWeighted(runtime,1);
    const z = parseInt(core[2],2)*50 + runtimeWeighted(runtime,2);

    const color = new THREE.Color(trust, evolution*0.5, decay);
    const geometry = new THREE.SphereGeometry(2 + evolution*2, 8, 8);
    const material = new THREE.MeshBasicMaterial({color: color, transparent:true, opacity:0.8});
    const sphere = new THREE.Mesh(geometry, material);
    sphere.position.set(x,y,z);
    sphere.userData = {vertexID, decay, entropy, trust, evolution};
    scene.add(sphere);
    return sphere;
}

function runtimeWeighted(runtime,index){
    // simple influence from runtime bits
    let sum = 0;
    for(let i=0;i<runtime.length;i++){
        sum += parseInt(runtime[i])*((i+1)/runtime.length)*5;
    }
    return sum*(index+1)/3;
}

