        const camera = new THREE.PerspectiveCamera(45, window.innerWidth/window.innerHeight, 0.1, 1000);
        camera.position.set(12,8,18); camera.lookAt(2,2,2);
        const renderer = new THREE.WebGLRenderer({antialias:true});
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true; controls.dampingFactor = 0.06;

        // ---------- VERTEX POINTS (with heatmap colors) ----------
        const offset = 0.18;
        const positions = [];
        vertices.forEach(v => {
            const px = v.x + v.w*offset;
            const py = v.y + v.w*offset*0.7;
            const pz = v.z + v.w*offset*0.9;
            positions.push(px, py, pz);
        });

        const geometry = new THREE.BufferGeometry();
        geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
        geometry.setAttribute('color', new THREE.Float32BufferAttribute(new Float32Array(vertices.length*3), 3));

        const material = new THREE.PointsMaterial({
            size: 0.45,
            vertexColors: true,
            transparent: true,
            blending: THREE.AdditiveBlending,
            sizeAttenuation: true
        });
        const points = new THREE.Points(geometry, material);
        scene.add(points);

        // ---------- EDGE LINES ----------
        const edgePositions = [];
        edges.forEach(([v1,v2]) => {
            edgePositions.push(
                v1.x + v1.w*offset, v1.y + v1.w*offset*0.7, v1.z + v1.w*offset*0.9,
                v2.x + v2.w*offset, v2.y + v2.w*offset*0.7, v2.z + v2.w*offset*0.9
            );
        });
        const edgeGeo = new THREE.BufferGeometry();
        edgeGeo.setAttribute('position', new THREE.Float32BufferAttribute(edgePositions, 3));
        const edgeMat = new THREE.LineBasicMaterial({ color: 0x88bbee, opacity: 0.2, transparent: true });
        const edgesMesh = new THREE.LineSegments(edgeGeo, edgeMat);
        scene.add(edgesMesh);

        // ---------- BOOT & STAGED TRIGGERS ----------
        const stateMap = vertices.map(v => v.state);
        const root = vertexMap.get('0,0,0,0');
        if(root) stateMap[root.index] = 1;
        let bootQueue = root ? [root.index] : [];
        const stagedTriggers = [];
        for(let i=0; i<10; i++){
            const v = vertices[Math.floor(Math.random() * vertices.length)];
            if(stateMap[v.index] === 0) stagedTriggers.push({index:v.index, timer:Math.random()*5000+2000});
        }

        // ---------- DEBUG UI ----------
        const debugToggle = document.getElementById('debug-toggle');
        const debugPanel = document.getElementById('debug-panel');
        const debugQueue = document.getElementById('debug-queue');
        const debugStaged = document.getElementById('debug-staged');
        const debugList = document.getElementById('debug-vertex-list');
        debugToggle.addEventListener('click', () => debugPanel.classList.toggle('collapsed'));

        function updateDebug() {
            debugQueue.innerText = `Boot queue: ${bootQueue.length}`;
            debugStaged.innerText = `Staged: ${stagedTriggers.length}`;
            let html = '';
            vertices.forEach((v,i) => {
                if(stateMap[i] !== 0) {
                    html += `[${v.x},${v.y},${v.z},${v.w}]: ${stateMap[i]===1?'boot':'verified'}<br>`;
                }
            });
            debugList.innerHTML = html;
        }

        // ---------- BOOT EXPANSION ----------
        function expandBoot() {
            if(bootQueue.length===0 && stagedTriggers.length===0) return;
            const newlyVerified = [...bootQueue];
            bootQueue = [];
            newlyVerified.forEach(idx => { if(stateMap[idx]===1) stateMap[idx]=2; });

            const candidates = new Set();
            newlyVerified.forEach(idx => {
                const v = vertices[idx];
                if(!v.isCore && v.success === 0) return;
                ['x','y','z','w'].forEach((d,i) => {
                    [-1,1].forEach(delta => {
                        const nx = v.x + (i===0?delta:0);
                        const ny = v.y + (i===1?delta:0);
                        const nz = v.z + (i===2?delta:0);
                        const nw = v.w + (i===3?delta:0);
                        if(nx<0||ny<0||nz<0||nw<0||nx>=DIM||ny>=DIM||nz>=DIM||nw>=DIM) return;
                        const neighbor = vertexMap.get(`${nx},${ny},${nz},${nw}`);
                        if(neighbor && stateMap[neighbor.index]===0 && (neighbor.isCore || neighbor.success>0))
                            candidates.add(neighbor.index);
                    });
                });
            });

            const arr = Array.from(candidates);
            arr.sort(() => Math.random()-0.5);
            arr.slice(0, Math.min(4, arr.length)).forEach(idx => { stateMap[idx]=1; bootQueue.push(idx); });

            for(let i=stagedTriggers.length-1; i>=0; i--){
                stagedTriggers[i].timer -= 1400;
                if(stagedTriggers[i].timer <= 0){
                    const idx = stagedTriggers[i].index;
                    if(stateMap[idx] === 0){ stateMap[idx]=1; bootQueue.push(idx); }
                    stagedTriggers.splice(i,1);
                }
            }
            updateDebug();
        }
        setInterval(expandBoot, 1400);

        // ---------- COLOR UPDATE LOOP ----------
        function updateColors() {
            const colors = geometry.attributes.color.array;
            let ptr = 0;
            vertices.forEach((v,i) => {
                const s = stateMap[i];
                let r,g,b;

                if(s === 1) {           // boot active
                    r=0.2; g=0.5; b=1.0;
                } else if(s === 2) {    // verified
                    r=0.2; g=1.0; b=0.4;
                } else if(v.isCore) {   // core
                    r=0.2; g=0.8; b=1.0;
                } else {
                    const sc = v.success;
                    // continuous heatmap: red (0) → orange (3) → green (7)
                    const t = sc / 7; // 0..1
                    if(sc <= 2) {
                        // red to orange
                        r = 1.0;
                        g = 0.3 + t * 0.5;  // 0.3→0.8
                        b = 0.2;
                    } else if(sc <= 4) {
                        // orange to yellow-green
                        r = 1.0 - (t-0.286)*0.5; // 1.0→0.86
                        g = 0.8 + (t-0.286)*0.2; // 0.8→0.86
                        b = 0.2;
                    } else {
                        // green
                        r = 0.2;
                        g = 0.9 + (t-0.714)*0.1; // 0.9→1.0
                        b = 0.3;
                    }
                }

                colors[ptr++] = r;
                colors[ptr++] = g;
                colors[ptr++] = b;
            });
            geometry.attributes.color.needsUpdate = true;
        }
        setInterval(updateColors, 200);

        // ---------- ANIMATION LOOP ----------
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }
        animate();

        // ---------- RESIZE HANDLER ----------
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        updateDebug();
    </script>
</body>
</html>
