<script>


// ------------------------------------------------
// CORE RDSC AXES
// ------------------------------------------------

const coreAxes = [

"Reality",
"Design",
"System",
"Cognition"

]


const coreMeaning = {

0:["Classical","Quantum"],
1:["LocalDesign","SharedDesign"],
2:["LocalSystem","DistributedSystem"],
3:["LowCognition","HighCognition"]

}


// ------------------------------------------------
// CORE VERTICES
// ------------------------------------------------

const coreVertices=[

{bits:"0000",arch:"Bare-metal firmware"},
{bits:"0001",arch:"Legacy mainframe"},
{bits:"0010",arch:"Early distributed DB"},
{bits:"0011",arch:"Google Spanner / S3"},
{bits:"0100",arch:"Embedded team systems"},
{bits:"0101",arch:"Classical simulation"},
{bits:"0110",arch:"Consensus systems"},
{bits:"0111",arch:"Cloud native Kubernetes"},
{bits:"1000",arch:"Quantum hardware firmware"},
{bits:"1001",arch:"Quantum frameworks"},
{bits:"1010",arch:"Quantum networking"},
{bits:"1011",arch:"Distributed quantum compute"},
{bits:"1100",arch:"Quantum hardware teams"},
{bits:"1101",arch:"Quantum algorithm collaboration"},
{bits:"1110",arch:"Quantum repeater networks"},
{bits:"1111",arch:"Global quantum internet"}

]


// ------------------------------------------------
// RUNTIME AXES (bits 4-15)
// ------------------------------------------------

const runtimeAxes=[

"Formal",
"Coherence",
"Boot",
"Trust",
"Network",
"Identity",
"Version",
"Fault",
"Privacy",
"Governance",
"Evolution",
"Misc"

]


// ------------------------------------------------
// VERTEX VALIDATION
// ------------------------------------------------

function normalizeHex(hex){

let v=parseInt(hex,16)

if(isNaN(v)) return null

return v.toString(16).padStart(4,"0")

}


function vertexBits(hex){

let n=parseInt(hex,16)

return n.toString(2).padStart(16,"0").split("").map(b=>+b)

}


function isValidVertex(hex){

hex=normalizeHex(hex)

if(!hex) return false

const bits=vertexBits(hex)

const coreSum=bits.slice(0,4).reduce((a,b)=>a+b,0)

const boot=bits[6]
const trust=bits[7]
const fault=bits[11]
const evolution=bits[14]

if(boot && coreSum===0) return false

if(trust && !boot) return false

if(evolution && !trust) return false

if(fault && !boot) return false

return true

}


// ------------------------------------------------
// RUNTIME FIBER GENERATOR
// ------------------------------------------------

function generateRuntimeVariants(coreBits,limit=32){

let variants=[]

for(let i=0;i<4096;i++){

let runtime=i.toString(2).padStart(12,"0")

let full=coreBits+runtime

let hex=parseInt(full,2).toString(16).padStart(4,"0").toUpperCase()

if(isValidVertex(hex)){

variants.push(hex)

if(variants.length>=limit) break

}

}

return variants

}


// ------------------------------------------------
// CORE SEMANTICS
// ------------------------------------------------

function coreLawDescription(bits){

let desc=[]

for(let i=0;i<4;i++){

let val=bits[i]

desc.push(coreMeaning[i][val])

}

return desc.join(" · ")

}


// ------------------------------------------------
// BUILD CORE GRID
// ------------------------------------------------

const grid=document.getElementById("core-grid")

coreVertices.forEach((v,i)=>{

const div=document.createElement("div")

div.className="vertex core"

if(i===0||i===5||i===10||i===15) div.classList.add("diagonal")

const laws=coreLawDescription(v.bits)

const runtimeList=generateRuntimeVariants(v.bits)

div.innerHTML=`

<h3>${v.bits}</h3>

<p><strong>Archetype:</strong> ${v.arch}</p>

<div class="core-law">${laws}</div>

<span class="arrow">Boot → Trust → Evolution</span>
<span class="arrow">Boot → Fault</span>

<div class="runtime">

<ul>

${runtimeList.map(r=>`<li>${r}</li>`).join("")}

</ul>

</div>

`

div.onclick=()=>{

const r=div.querySelector(".runtime")

r.style.display=r.style.display==="block"?"none":"block"

}

grid.appendChild(div)

})


// ------------------------------------------------
// HAMMING DISTANCE
// ------------------------------------------------

function hammingDistance(a,b){

a=parseInt(normalizeHex(a),16)

b=parseInt(normalizeHex(b),16)

let xor=a^b

let count=0

while(xor){

count+=xor&1
xor>>=1

}

return count

}


// ------------------------------------------------
// MULTI SYSTEM COMPARISON
// ------------------------------------------------

function compareVertices(){

const a=document.getElementById("vertexA").value.trim()
const b=document.getElementById("vertexB").value.trim()

if(!a||!b){

alert("Enter both vertex IDs")

return

}

const validA=isValidVertex(a)
const validB=isValidVertex(b)

const dist=hammingDistance(a,b)

let result=`Hamming distance: ${dist}<br>`

result+=`Vertex A valid: ${validA}<br>`
result+=`Vertex B valid: ${validB}<br>`

document.getElementById("comparison-result").innerHTML=result

}

