<script type="module">
import * as THREE from 'three';

// ── Inline OrbitControls ──────────────────────────────────────────────────
class OrbitControls {
  constructor(cam, el) {
    this.cam=cam; this.el=el;
    this.target=new THREE.Vector3(1.5,1.5,1.5);
    this._phi=1.05; this._theta=0.55; this._r=11;
    this._tp=this._phi; this._tt=this._theta; this._tr=this._r;
    this._drag=false; this._lm={x:0,y:0};
    el.addEventListener('mousedown',e=>{this._drag=true;this._lm={x:e.clientX,y:e.clientY};});
    window.addEventListener('mouseup',()=>this._drag=false);
    window.addEventListener('mousemove',e=>{
      if(!this._drag) return;
      this._tt-=(e.clientX-this._lm.x)*0.007;
      this._tp=Math.max(.08,Math.min(Math.PI-.08,this._tp+(e.clientY-this._lm.y)*0.007));
      this._lm={x:e.clientX,y:e.clientY};
    });
    el.addEventListener('wheel',e=>{
      e.preventDefault();
      this._tr=Math.max(3,Math.min(28,this._tr+e.deltaY*0.018));
    },{passive:false});
  }
  update() {
    this._phi+=(this._tp-this._phi)*.07;
    this._theta+=(this._tt-this._theta)*.07;
    this._r+=(this._tr-this._r)*.07;
    this.cam.position.set(
      this.target.x+this._r*Math.sin(this._phi)*Math.cos(this._theta),
      this.target.y+this._r*Math.cos(this._phi),
      this.target.z+this._r*Math.sin(this._phi)*Math.sin(this._theta)
    );
    this.cam.lookAt(this.target);
  }
}

// ── Scene setup ───────────────────────────────────────────────────────────
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x04060e);
scene.fog=new THREE.FogExp2(0x04060e, 0.035);

const cam=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,200);
const renderer=new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
document.body.appendChild(renderer.domElement);

const controls=new OrbitControls(cam,renderer.domElement);

// Lights
scene.add(new THREE.AmbientLight(0x0d1830,3));
const dl=new THREE.DirectionalLight(0xffffff,1.2); dl.position.set(4,7,5); scene.add(dl);
const pl1=new THREE.PointLight(0x1a3a7a,2,18); pl1.position.set(-2,4,6); scene.add(pl1);
const pl2=new THREE.PointLight(0xffd700,0.5,12); pl2.position.set(3,-1,3); scene.add(pl2);

// ── Heatmap gradient canvas ───────────────────────────────────────────────
const hgCanvas=document.getElementById('heatgradient');
const hgCtx=hgCanvas.getContext('2d');
const hg=hgCtx.createLinearGradient(0,0,140,0);
hg.addColorStop(0,'#1a2640');
hg.addColorStop(0.3,'#6366f1');
hg.addColorStop(0.5,'#38bdf8');
hg.addColorStop(0.7,'#84cc16');
hg.addColorStop(1,'#00ffc8');
hgCtx.fillStyle=hg; hgCtx.fillRect(0,0,140,8);

// ── Color functions ───────────────────────────────────────────────────────
// success 0 = inactive (pre-boot), 4–8 = heatmap active
function heatRGB(success, active) {
  if(!active) return [0.06,0.1,0.18];  // dark inactive
  // 4=peak(1111), 8=origin(0000)
  const t=(success-4)/4; // 0 at peak, 1 at origin
  // Interpolate: violet(0.39,0.38,0.98) → cyan(0.22,0.74,0.98) → lime(0.52,0.80,0.09) → teal(0.0,1.0,0.78)
  if(t<0.33) {
    const s=t/0.33;
    return [0.39+(0.22-0.39)*s, 0.38+(0.74-0.38)*s, 0.98*1];
  } else if(t<0.66) {
    const s=(t-0.33)/0.33;
    return [0.22+(0.52-0.22)*s, 0.74+(0.80-0.74)*s, 0.98+(0.09-0.98)*s];
  } else {
    const s=(t-0.66)/0.34;
    return [0.52+(0.0-0.52)*s, 0.80+(1.0-0.80)*s, 0.09+(0.78-0.09)*s];
  }
}

// ── 4D→3D projection ─────────────────────────────────────────────────────
const W=0.24;
function p4(c) {
  return new THREE.Vector3(c[0]*3+c[3]*W*3, c[1]*3+c[3]*W*2, c[2]*3+c[3]*W*2.5);
}

// ── Axis edge colors ──────────────────────────────────────────────────────
const AXIS_C=[0xf97316,0x38bdf8,0xa78bfa,0x34d399];

// ── Build scene objects ───────────────────────────────────────────────────
const L=LATTICE;
const verts=L.vertices;
const edges=L.edges;

// Sphere geometry per size tier
const geoSmall=new THREE.SphereGeometry(.15,14,10);
const geoMed  =new THREE.SphereGeometry(.20,16,12);
const geoDiag =new THREE.SphereGeometry(.27,20,16);

const nodeMeshes=[];
const nodeIdx={};
const nodeMats=[];

verts.forEach((v,i)=>{
  const pos=p4(v.coords);
  const isDiag=v.is_diagonal;
  const hw=v.hamming_weight;

  const rgb=heatRGB(0, false); // start inactive
  const mat=new THREE.MeshStandardMaterial({
    color:new THREE.Color(...rgb),
    emissive:new THREE.Color(0,0,0),
    roughness:.4, metalness:.5,
  });
  nodeMats.push(mat);

  const geo=isDiag?geoDiag:(hw<=1||hw>=3?geoMed:geoSmall);
  const mesh=new THREE.Mesh(geo,mat);
  mesh.position.copy(pos);
  mesh.userData=v;
  scene.add(mesh);
  nodeMeshes.push(mesh);
  nodeIdx[v.id]=i;
});

// ── Glow sprites for diagonal nodes ──────────────────────────────────────
function makeGlowTex(colorStr) {
  const c=document.createElement('canvas'); c.width=64; c.height=64;
  const ctx=c.getContext('2d');
  const g=ctx.createRadialGradient(32,32,0,32,32,32);
  g.addColorStop(0,colorStr.replace(')',',0.7)').replace('rgb','rgba'));
  g.addColorStop(.5,colorStr.replace(')',',0.25)').replace('rgb','rgba'));
  g.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=g; ctx.fillRect(0,0,64,64);
  return new THREE.CanvasTexture(c);
}
const glowTexDiag=makeGlowTex('rgb(255,215,0)');
const glowSprites=[];
verts.filter(v=>v.is_diagonal).forEach(v=>{
  const sm=new THREE.SpriteMaterial({
    map:glowTexDiag,transparent:true,blending:THREE.AdditiveBlending,depthWrite:false,opacity:0
  });
  const s=new THREE.Sprite(sm);
  s.scale.set(1.4,1.4,1.4);
  s.position.copy(p4(v.coords));
  scene.add(s);
  glowSprites.push({sprite:s,id:v.id});
});

// ── Edges grouped by axis ─────────────────────────────────────────────────
const edgeLineSets=[];
[0,1,2,3].forEach(ax=>{
  const pos=[];
  edges.filter(e=>e.axis===ax).forEach(e=>{
    pos.push(...Object.values(p4(e.from)));
    pos.push(...Object.values(p4(e.to)));
  });
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
  const mat=new THREE.LineBasicMaterial({color:AXIS_C[ax],opacity:.3,transparent:true});
  const ls=new THREE.LineSegments(geo,mat);
  scene.add(ls);
  edgeLineSets.push({ls,mat});
});

// ── Diagonal glow line (animated) ─────────────────────────────────────────
const diagPos=[];
L.diagonal.forEach(d=>{const p=p4(d);diagPos.push(p.x,p.y,p.z);});
const diagGeo=new THREE.BufferGeometry();
diagGeo.setAttribute('position',new THREE.Float32BufferAttribute(diagPos,3));
const diagLineMat=new THREE.LineBasicMaterial({color:0xffd700,opacity:0,transparent:true});
const diagLine=new THREE.Line(diagGeo,diagLineMat);
scene.add(diagLine);

// ── Floor grid ────────────────────────────────────────────────────────────
const grid=new THREE.GridHelper(12,12,0x0c1420,0x0c1420);
grid.position.set(1.5,-.5,1.5); scene.add(grid);

// ── Cycle bar ─────────────────────────────────────────────────────────────
const dotsEl=document.getElementById('cycle-dots');
const dotEls=[];
for(let i=0;i<7;i++){
  const d=document.createElement('div');
  d.className='cdot';
  dotsEl.appendChild(d);
  dotEls.push(d);
}

// ── Boot state ────────────────────────────────────────────────────────────
let bootCycle=0;
let activeIds=new Set();
let scalePulse={}; // id → {t, baseScale}
let cycleInterval=null;

function getNodeColor(v) {
  const active=activeIds.has(v.id);
  return heatRGB(active?v.success:0, active);
}

function setNodeColor(mesh, mat, rgb, emissiveMult=0.25) {
  const c=new THREE.Color(...rgb);
  mat.color.set(c);
  mat.emissive.set(c.clone().multiplyScalar(emissiveMult));
}

function resetBoot() {
  clearInterval(cycleInterval);
  bootCycle=0;
  activeIds=new Set();
  scalePulse={};

  // Reset all nodes to inactive
  verts.forEach((v,i)=>{
    setNodeColor(nodeMeshes[i],nodeMats[i],heatRGB(0,false),0);
    nodeMeshes[i].scale.set(.95,.95,.95);
  });
  // Reset diagonal glows
  glowSprites.forEach(gs=>{gs.sprite.material.opacity=0;});
  diagLineMat.opacity=0;
  dotEls.forEach(d=>{d.classList.remove('active','done');});
  document.getElementById('s-active').textContent='0';
  document.getElementById('s-cycle').textContent='0 / 7';
  document.getElementById('cycle-status').textContent='Reset — click to restart';
  edgeLineSets.forEach(e=>{e.mat.opacity=.15;});

  setTimeout(startBoot, 600);
}

function startBoot() {
  bootCycle=0;
  runCycle(); // immediate
  cycleInterval=setInterval(runCycle, 1400);
}

function runCycle() {
  if(bootCycle>7) { clearInterval(cycleInterval); return; }

  // Activate all nodes with cycle_reached === bootCycle
  const newlyActive=verts.filter(v=>v.cycle_reached===bootCycle && !activeIds.has(v.id));
  newlyActive.forEach(v=>{
    activeIds.add(v.id);
    const i=nodeIdx[v.id];
    const rgb=getNodeColor(v);
    setNodeColor(nodeMeshes[i],nodeMats[i],rgb, v.is_diagonal?0.5:0.3);
    // Pulse scale
    scalePulse[v.id]={t:0};
    // Diagonal glow
    if(v.is_diagonal) {
      const gs=glowSprites.find(g=>g.id===v.id);
      if(gs) gs.sprite.material.opacity=0.0; // will fade in via animate
    }
  });

  // Update diagonal line opacity as diagonal nodes activate
  const diagActive=L.diagonal.filter(d=>activeIds.has(d.join('')));
  diagLineMat.opacity=Math.min(0.85, diagActive.length/5*0.85);

  // Edge opacity: brighter as more nodes activate
  const ratio=activeIds.size/16;
  edgeLineSets.forEach((e,i)=>{
    e.mat.opacity=0.12+ratio*0.28;
  });

  // Update UI
  document.getElementById('s-active').textContent=activeIds.size;
  document.getElementById('s-cycle').textContent=`${bootCycle} / 7`;

  if(bootCycle>0 && bootCycle<=7) {
    dotEls[bootCycle-1].classList.add('active');
    if(bootCycle>1) dotEls[bootCycle-2].classList.remove('active');
    dotEls[bootCycle-1].classList.add('done');
  }

  const labels=['Initializing…','Hamming-1 frontier','Hamming-2 activated','Hamming-3 activated','Peak reached!','Propagating…','Propagating…','Complete ✓'];
  document.getElementById('cycle-status').textContent=
    bootCycle<labels.length ? labels[bootCycle] : 'Complete ✓';

  bootCycle++;
  if(bootCycle>7) clearInterval(cycleInterval);
}

// ── Raycasting ────────────────────────────────────────────────────────────
const ray=new THREE.Raycaster();
const mouse=new THREE.Vector2();
renderer.domElement.addEventListener('click',e=>{
  mouse.x=(e.clientX/innerWidth)*2-1;
  mouse.y=-(e.clientY/innerHeight)*2+1;
  ray.setFromCamera(mouse,cam);
  const hits=ray.intersectObjects(nodeMeshes);
  if(!hits.length) return;
  const v=hits[0].object.userData;
  const active=activeIds.has(v.id);
  const upEdges=edges.filter(e=>e.from.join('')===v.id).length;
  document.getElementById('ni-id').textContent=v.id;
  document.getElementById('ni-arch').textContent=v.archetype;
  document.getElementById('ni-s').textContent=active?`${v.success}/8`:'inactive';
  document.getElementById('ni-s').style.color=active?'#c8d8ec':'#2a3d56';
  document.getElementById('ni-cr').textContent=v.cycle_reached===0?'Origin (0)':`Cycle ${v.cycle_reached}`;
  document.getElementById('ni-hw').textContent=v.hamming_weight;
  document.getElementById('ni-up').textContent=upEdges;
  document.getElementById('ni-st').textContent=active?'Active':'Pre-boot';
  document.getElementById('ni-st').style.color=active?'#10b981':'#334155';
  const diagEl=document.getElementById('ni-diag');
  if(v.is_diagonal) {
    diagEl.style.display='block';
    diagEl.textContent=`⬡ ${v.level} — t ≈ ${v.t.toFixed(1)}`;
  } else diagEl.style.display='none';
  // Heatbar
  const rgb=getNodeColor(v);
  const c=new THREE.Color(...rgb);
  document.getElementById('ni-heatbar').style.background=`rgb(${Math.round(c.r*255)},${Math.round(c.g*255)},${Math.round(c.b*255)})`;
  document.getElementById('nodeinfo').style.display='block';
});

// ── Animate loop ──────────────────────────────────────────────────────────
let frame=0;
function animate() {
  requestAnimationFrame(animate);
  frame++;
  controls.update();

  // Scale pulse for newly activated nodes
  Object.keys(scalePulse).forEach(id=>{
    const sp=scalePulse[id];
    sp.t+=0.1;
    if(sp.t<Math.PI) {
      const s=1+Math.sin(sp.t)*0.45*(1-sp.t/Math.PI);
      nodeMeshes[nodeIdx[id]]?.scale.set(s,s,s);
    } else {
      nodeMeshes[nodeIdx[id]]?.scale.set(1,1,1);
      delete scalePulse[id];
    }
  });

  // Subtle breathing on active nodes
  verts.forEach((v,i)=>{
    if(activeIds.has(v.id) && !scalePulse[v.id]) {
      const s = v.is_diagonal
        ? 1+0.06*Math.sin(frame*0.04+i*0.7)
        : 1+0.03*Math.sin(frame*0.03+i*0.9);
      nodeMeshes[i].scale.set(s,s,s);
    } else if(!activeIds.has(v.id)) {
      const s=0.9+0.04*Math.sin(frame*0.025+i*1.1);
      nodeMeshes[i].scale.set(s,s,s);
    }
  });

  // Fade in diagonal glow sprites
  glowSprites.forEach(gs=>{
    if(activeIds.has(gs.id)) {
      gs.sprite.material.opacity=Math.min(.85, gs.sprite.material.opacity+.015);
    }
  });

  // Diagonal line pulse
  if(diagLineMat.opacity>0) {
    diagLineMat.opacity=diagLineMat.opacity*.997+0.003*Math.sin(frame*0.03)*0.1;
  }

  // Rotate diagonal nodes slowly
  verts.forEach((v,i)=>{
    if(v.is_diagonal) nodeMeshes[i].rotation.y+=0.008;
  });

  renderer.render(scene,cam);
}

animate();
startBoot();

window.resetBoot=resetBoot;
window.addEventListener('resize',()=>{
  cam.aspect=innerWidth/innerHeight;
  cam.updateProjectionMatrix();
  renderer.setSize(innerWidth,innerHeight);
});
</script>

