#!/usr/bin/env bash
set -euo pipefail

SESSION_ID=$(uuidgen)
export NEXUS_SESSION_ID="$SESSION_ID"
ROOT_DIR=$(pwd)

echo "🎯 Build Session: $SESSION_ID"

run_step() {
  local step_num="$1"
  local step_name="$2"
  local py_code="$3"

  echo "➡️ Step $step_num: $step_name"

  tmpfile=$(mktemp --suffix=.py)
  cat > "$tmpfile" <<PYTHON
import os
from ollama_client import ask_with_training
$py_code
ask_with_training(
    step=$step_num,
    step_name='$step_name',
    substep='main',
    user_content=prompt,
    budget=400,
    session_id=os.environ.get('NEXUS_SESSION_ID','unknown')
)
PYTHON

  python3 "$tmpfile"
  rm "$tmpfile"
  echo "✅ Step $step_num completed"
}

# --- Steps ---

run_step 0 "ground" "prompt=open('$ROOT_DIR/user_prompt.txt').read() if os.path.exists('$ROOT_DIR/user_prompt.txt') else input('Enter build intent: ')"
run_step 1 "compress" "prompt='compress user intent to minimal efficient prompt'"
run_step 2 "mockui" "prompt='generate mock UI structure for engine builder'"
run_step 3 "parse" "from bs4 import BeautifulSoup; html_content='...'; prompt='parse visible buttons and requirements from HTML'"
run_step 4 "dag" "prompt='generate DAG topographical map from parsed requirements'"
run_step 5 "tasks" "prompt='create task.json based on DAG'"
run_step 6 "build" "prompt='train pipeline using only positive memory dumps; drop memory at end of step'"

echo "🎉 Build complete!"
echo "Output: $ROOT_DIR/output.zip"
echo "Training Data: $ROOT_DIR/training_data/"
