# Cron runner (dependency-aware, with locking)
cat > scripts/cron_runner.py << 'PY'
import json, time, subprocess, fcntl
from pathlib import Path
from threading import Thread

LOCK_DIR = Path("locks")
LOCK_DIR.mkdir(exist_ok=True)

def update_task_status(task_id, status, error=None):
    tasks = json.load(open("tasks.json"))
    for t in tasks["tasks"]:
        if t["id"] == task_id:
            t["status"] = status
            if error:
                t["error"] = error
    open("tasks.json", "w").write(json.dumps(tasks, indent=2))

def run_one(task_id):
    lock = LOCK_DIR / f"{task_id}.lock"
    with open(lock, "w") as lf:
        fcntl.flock(lf, fcntl.LOCK_EX)
        tasks = json.load(open("tasks.json"))
        cur = next((t for t in tasks["tasks"] if t["id"] == task_id), None)
        if cur and cur["status"] == "complete":
            return
        update_task_status(task_id, "running")
        proc = subprocess.run(["python3", "pipeline/build_one.py", task_id])
        if proc.returncode == 0:
            update_task_status(task_id, "complete")
        else:
            update_task_status(task_id, "failed", f"Exit code {proc.returncode}")

def worker(sched_entry):
    while True:
        tasks = json.load(open("tasks.json"))
        deps_ok = all(
            next((t for t in tasks["tasks"] if t["id"] == d), {}).get("status") == "complete"
            for d in sched_entry["depends_on"]
        )
        if deps_ok:
            break
        time.sleep(2)
    print(f"Task {sched_entry['id']} waiting {sched_entry['delay_seconds']}s")
    time.sleep(sched_entry['delay_seconds'])
    run_one(sched_entry['id'])

def main():
    schedule = json.load(open("cron_schedule.json"))
    threads = []
    for entry in schedule:
        t = Thread(target=worker, args=(entry,))
        t.start()
        threads.append(t)
    for t in threads:
        t.join()
    print("All tasks executed.")

if __name__ == "__main__":
    main()
