cat > pipeline/ollama_client.py << 'PY'
import json, re, time, hashlib, urllib.request, os
from pathlib import Path
from datetime import datetime

OLLAMA_HOST = "http://172.30.80.1:11434"
MODEL = "gemma4:26b"

BASE = Path(__file__).parent.parent
TRAIN = BASE / "training_data"
CACHE = BASE / "tool_cache"
SESSION = os.environ.get("NEXUS_SESSION_ID", "unknown")

for d in [TRAIN, TRAIN/"raw", CACHE]:
    d.mkdir(exist_ok=True)

def clean(x):
    return re.sub(r'^```.*?\n|```$', '', x, flags=re.S).strip()

def safe_json(x):
    try:
        return json.loads(clean(x))
    except:
        return {"error": "bad_json", "raw": x}

def cache_key(data):
    return hashlib.md5(json.dumps(data, sort_keys=True).encode()).hexdigest()

def cache_get(k):
    f = CACHE / f"{k}.json"
    return json.loads(f.read_text()) if f.exists() else None

def cache_set(k, v):
    (CACHE / f"{k}.json").write_text(json.dumps(v))

def ask(prompt, budget=500, require_tools=False):
    sys_msg = f"JSON ONLY. Stateless. Max {budget} tokens."
    if require_tools:
        sys_msg += " Use web_search/fetch_url if knowledge may be outdated (cutoff before 2025-04-01)."
    payload = {
        "model": MODEL,
        "messages": [
            {"role": "system", "content": sys_msg},
            {"role": "user", "content": prompt}
        ],
        "stream": False,
        "options": {"temperature": 0.15, "num_predict": budget}
    }
    req = urllib.request.Request(
        f"{OLLAMA_HOST}/api/chat",
        data=json.dumps(payload).encode(),
        headers={"Content-Type": "application/json"}
    )
    with urllib.request.urlopen(req, timeout=60) as resp:
        return json.loads(resp.read().decode())["message"]["content"]

def dump_training(step, step_name, substep, user_prompt, teacher_raw, parsed, latency_ms):
    example = {
        "timestamp": datetime.utcnow().isoformat(),
        "session": SESSION,
        "step": step,
        "step_name": step_name,
        "substep": substep,
        "user_prompt": user_prompt,
        "teacher_raw": teacher_raw,
        "parsed": parsed,
        "latency_ms": latency_ms
    }
    with open(TRAIN / "stream.jsonl", "a") as f:
        f.write(json.dumps(example) + "\n")
    raw_dir = TRAIN / "raw" / f"{SESSION}_{step}_{substep}"
    raw_dir.mkdir(parents=True, exist_ok=True)
    (raw_dir / "example.json").write_text(json.dumps(example, indent=2))
    (raw_dir / "teacher_raw.txt").write_text(teacher_raw)

def run(step, step_name, substep, user_prompt, budget=500, require_tools=False):
    start = time.time()
    raw = ask(user_prompt, budget, require_tools)
    latency = int((time.time() - start) * 1000)
    parsed = safe_json(raw)
    dump_training(step, step_name, substep, user_prompt, raw, parsed, latency)
    return parsed
