import torch
from transformers import AutoModelForCausalLM, AutoTokenizer, BitsAndBytesConfig
from peft import LoraConfig, get_peft_model, PeftModel
from pathlib import Path
import json

STUDENT_BASE = "google/gemma-2-9b-it"
LORA_PATH = Path(__file__).parent.parent / "student_model"
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
LR = 5e-4

_model = None
_tokenizer = None
_peft = None
_optim = None

def _load():
    global _model, _tokenizer, _peft, _optim
    if _model is not None:
        return
    bnb = BitsAndBytesConfig(load_in_4bit=True, bnb_4bit_use_double_quant=True, bnb_4bit_quant_type="nf4", bnb_4bit_compute_dtype=torch.float16)
    _tokenizer = AutoTokenizer.from_pretrained(STUDENT_BASE)
    _model = AutoModelForCausalLM.from_pretrained(STUDENT_BASE, quantization_config=bnb, device_map="auto", torch_dtype=torch.float16)
    if (LORA_PATH / "adapter_config.json").exists():
        _peft = PeftModel.from_pretrained(_model, LORA_PATH)
    else:
        lora = LoraConfig(r=16, lora_alpha=32, target_modules=["q_proj","k_proj","v_proj","o_proj"], lora_dropout=0.05, bias="none", task_type="CAUSAL_LM")
        _peft = get_peft_model(_model, lora)
    _peft.train()
    _optim = torch.optim.AdamW(_peft.parameters(), lr=LR)

def update_student(example):
    _load()
    prompt = f"System: {example['system_prompt']}\nUser: {example['user_prompt']}\nAssistant:"
    target = example['teacher_raw']
    inputs = _tokenizer(prompt, return_tensors="pt", truncation=True, max_length=1024).to(DEVICE)
    targets = _tokenizer(target, return_tensors="pt", truncation=True, max_length=1024).to(DEVICE)
    full_ids = torch.cat([inputs.input_ids, targets.input_ids], dim=1)
    outputs = _peft(full_ids, labels=full_ids)
    loss = outputs.loss
    loss.backward()
    torch.nn.utils.clip_grad_norm_(_peft.parameters(), 1.0)
    _optim.step()
    _optim.zero_grad()
    _peft.save_pretrained(LORA_PATH)
    _tokenizer.save_pretrained(LORA_PATH)
