function uid() {
return Math.random().toString(36).slice(2, 9);
}

function makeEntry() {
return {
id: uid(),
inputContract:  { description: “”, type: “”, shape: “”, constraints: “” },
outputContract: { description: “”, type: “”, shape: “”, sideEffects: “” },
};
}

// ─── DRIFT ENGINE ────────────────────────────────────────────────────────────

function tokenize(str) {
return str.toLowerCase().replace(/[^a-z0-9]/g, “ “).split(/\s+/).filter(Boolean);
}

function jaccardSim(a, b) {
const sa = new Set(tokenize(a));
const sb = new Set(tokenize(b));
if (!sa.size && !sb.size) return 1;
const inter = […sa].filter(x => sb.has(x)).length;
const union = new Set([…sa, …sb]).size;
return union === 0 ? 1 : inter / union;
}

// Type lossiness: rough heuristic on collection→scalar compression
const TYPE_RANK = { “list”: 4, “dict”: 3, “set”: 3, “tuple”: 3, “str”: 2, “int”: 1, “float”: 1, “bool”: 1, “none”: 0, “any”: 2 };
function typeRank(t) {
const low = t.toLowerCase();
for (const [k, v] of Object.entries(TYPE_RANK)) if (low.includes(k)) return v;
return 2;
}
function typeIntegrityScore(inType, outType) {
if (!inType || !outType) return 0.5; // unknown → neutral
const diff = typeRank(inType) - typeRank(outType);
// Large drop = lossy = drift; same/up = clean
if (diff <= 0) return 0.0;
if (diff === 1) return 0.25;
if (diff === 2) return 0.55;
return 0.85;
}

// Constraint leakage: tokens in constraints not mirrored in sideEffects
function constraintLeakage(constraints, sideEffects) {
if (!constraints) return 0;
const cToks = new Set(tokenize(constraints));
const sToks = new Set(tokenize(sideEffects));
if (!cToks.size) return 0;
const unresolved = […cToks].filter(t => !sToks.has(t)).length;
return Math.min(unresolved / cToks.size, 1);
}

// Shape compression: token count ratio
function shapeCompression(inShape, outShape) {
const ic = tokenize(inShape).length;
const oc = tokenize(outShape).length;
if (!ic && !oc) return 0;
if (!ic) return 0;
const ratio = oc / (ic || 1);
if (ratio >= 0.6) return 0.0;
if (ratio >= 0.35) return 0.3;
if (ratio >= 0.15) return 0.6;
return 0.9;
}

// Completeness: penalise empty fields
function completenessScore(entry) {
const all = [
…Object.values(entry.inputContract),
…Object.values(entry.outputContract),
];
const empty = all.filter(v => !v.trim()).length;
return empty / all.length;
}

function computeDrift(entry) {
const ic = entry.inputContract;
const oc = entry.outputContract;

const semantic   = 1 - jaccardSim(ic.description, oc.description);   // low sim = high drift
const typeInt    = typeIntegrityScore(ic.type, oc.type);
const leakage    = constraintLeakage(ic.constraints, oc.sideEffects);
const compression= shapeCompression(ic.shape, oc.shape);
const completeness = completenessScore(entry);

const weights = { semantic: 0.30, typeInt: 0.20, leakage: 0.20, compression: 0.15, completeness: 0.15 };
const composite =
semantic    * weights.semantic +
typeInt     * weights.typeInt +
leakage     * weights.leakage +
compression * weights.compression +
completeness* weights.completeness;

return {
composite: Math.round(composite * 100) / 100,
breakdown: {
semantic:    Math.round(semantic    * 100) / 100,
typeInt:     Math.round(typeInt     * 100) / 100,
leakage:     Math.round(leakage     * 100) / 100,
compression: Math.round(compression* 100) / 100,
completeness:Math.round(completeness*100) / 100,
},
};
}

function driftColor(score) {
if (score <= 0.30) return “#7ee787”;
if (score <= 0.60) return “#e3b341”;
return “#f85149”;
}
function driftLabel(score) {
if (score <= 0.30) return “CLEAN”;
if (score <= 0.60) return “WARN”;
return “DRIFT”;
}

