// ── BLACK HOLE SIM ──
const BlackHoleSim = (() => {
  let canvas, ctx, raf, t = 0;
  let distance = 10; // in Schwarzschild radii
  let quizDone = false;

  // Gravitational time dilation: t' = t * sqrt(1 - 2GM/rc^2) = t * sqrt(1 - 1/r_s)
  // where r_s is distance in Schwarzschild radii (rs = 2GM/c^2)
  // Factor: sqrt(1 - 1/x) where x = r/rs
  function gravFactor(rs_dist) {
    if (rs_dist <= 1) rs_dist = 1.001;
    return Math.sqrt(1 - 1 / rs_dist);
  }

  function init() {
    canvas = document.getElementById('blackhole-canvas');
    ctx = canvas.getContext('2d');
    canvas.width = Math.min(700, window.innerWidth - 48);
    canvas.height = 380;
    cancelAnimationFrame(raf);
    update(distance);
    animate();
  }

  function update(val) {
    distance = parseFloat(val);
    document.getElementById('bh-distance-label').textContent = distance.toFixed(1);
    const factor = gravFactor(distance);
    const twinATime = 1 * factor; // twin A experiences slowed time
    const twinBTime = 1;
    const diff = twinBTime - twinATime;

    document.getElementById('bh-twin-a').textContent = (twinATime * 100).toFixed(3) + ' min';
    document.getElementById('bh-twin-b').textContent = (twinBTime * 100).toFixed(3) + ' min';
    document.getElementById('bh-diff').textContent = (diff * 100).toFixed(3) + ' min';

    let fact;
    if (distance <= 1.5) fact = '🔴 EXTREME! At the event horizon, time stops entirely from outside! Nothing escapes — not even light!';
    else if (distance <= 3) fact = '⚠️ Extreme gravitational dilation! Twin A experiences time at ' + (factor*100).toFixed(1) + '% of Twin B\'s rate. They would return MUCH younger!';
    else if (distance <= 8) fact = '🌀 Strong gravitational effect! Twin A\'s clock runs at ' + (factor*100).toFixed(1) + '% of Twin B\'s clock. The singularity\'s gravity warps spacetime!';
    else if (distance <= 20) fact = '🪐 Moderate gravitational dilation. Further from the singularity, time dilation weakens. This is how GPS satellite corrections work!';
    else fact = '⭐ At large distances, gravitational time dilation is negligible — but still real! Earth\'s gravity causes GPS clocks to run 45 microseconds fast per day.';
    document.getElementById('bh-fact').textContent = fact;
  }

  function animate() {
    if (!canvas) return;
    t++;
    draw();
    raf = requestAnimationFrame(animate);
  }

  function draw() {
    const W = canvas.width, H = canvas.height;
    ctx.clearRect(0, 0, W, H);

    const cx = W * 0.38, cy = H * 0.5;
    const factor = gravFactor(distance);

    // ── GRAVITATIONAL LENSING RINGS ──
    for (let i = 10; i >= 1; i--) {
      const r = 40 + i * 22;
      const grd = ctx.createRadialGradient(cx, cy, r*0.6, cx, cy, r);
      const alpha = (0.06 - i * 0.005) * (1 + (1-factor)*2);
      grd.addColorStop(0, `rgba(255,100,0,${Math.max(0,alpha*2)})`);
      grd.addColorStop(0.5, `rgba(200,50,200,${Math.max(0,alpha)})`);
      grd.addColorStop(1, 'transparent');
      ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2);
      ctx.fillStyle = grd; ctx.fill();
    }

    // Accretion disk
    for (let i = 0; i < 360; i += 2) {
      const rad = (i * Math.PI) / 180;
      const dr = 52 + Math.sin(i * 3 + t * 0.05) * 8;
      const dr2 = 100 + Math.sin(i * 2 + t * 0.03) * 12;
      const xA = cx + Math.cos(rad) * dr, yA = cy + Math.sin(rad) * dr * 0.35;
      const xB = cx + Math.cos(rad) * dr2, yB = cy + Math.sin(rad) * dr2 * 0.35;
      const hot = (i % 90 < 45) ? 255 : 200;
      ctx.strokeStyle = `rgba(${hot},${Math.floor(hot*0.4)},0,0.7)`;
      ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(xA, yA); ctx.lineTo(xB, yB); ctx.stroke();
    }

    // Bright inner ring (photon sphere)
    ctx.beginPath(); ctx.arc(cx, cy, 48, 0, Math.PI*2);
    ctx.strokeStyle = 'rgba(255,200,100,0.6)'; ctx.lineWidth = 2;
    ctx.shadowBlur = 12; ctx.shadowColor = '#ff9100'; ctx.stroke(); ctx.shadowBlur = 0;

    // Event horizon
    ctx.beginPath(); ctx.arc(cx, cy, 36, 0, Math.PI*2);
    ctx.fillStyle = '#000'; ctx.fill();
    ctx.strokeStyle = 'rgba(255,100,0,0.8)'; ctx.lineWidth = 2.5;
    ctx.shadowBlur = 20; ctx.shadowColor = '#ff6600'; ctx.stroke(); ctx.shadowBlur = 0;

    // Singularity label
    ctx.fillStyle = 'rgba(255,80,0,0.9)';
    ctx.font = '700 10px Nunito'; ctx.textAlign = 'center';
    ctx.fillText('SINGULARITY', cx, cy + 4);
    ctx.fillStyle = 'rgba(255,255,255,0.4)';
    ctx.font = '600 9px Nunito';
    ctx.fillText('Event Horizon', cx, cy + 52);
    ctx.textAlign = 'left';

    // Photon sphere label
    ctx.fillStyle = 'rgba(255,200,100,0.7)';
    ctx.font = '600 9px Nunito';
    ctx.textAlign = 'center';
    ctx.fillText('Photon Sphere (1.5 rs)', cx, cy - 54);
    ctx.textAlign = 'left';

    // ── TWIN A (near black hole) ──
    const twAX = cx + 36 + (distance / 50) * (W * 0.28);
    const twAY = cy - 20;
    drawTwin(twAX, twAY, '#ff5252', 'Twin A', `near BH\n${distance.toFixed(1)} rs`, t * 0.04 * factor, factor);

    // Connection line from BH to Twin A
    ctx.setLineDash([4, 4]);
    ctx.strokeStyle = 'rgba(255,82,82,0.3)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(cx + 36, cy); ctx.lineTo(twAX - 22, twAY); ctx.stroke();
    ctx.setLineDash([]);

    // Distance label
    ctx.fillStyle = 'rgba(255,82,82,0.6)';
    ctx.font = '600 9px Nunito'; ctx.textAlign = 'center';
    ctx.fillText(`← ${distance.toFixed(1)} Schwarzschild radii →`, cx + 36 + (twAX - cx - 36)/2, cy + 14);
    ctx.textAlign = 'left';

    // ── TWIN B (far away) ──
    const twBX = W * 0.84, twBY = H * 0.28;
    drawTwin(twBX, twBY, '#00e5ff', 'Twin B', 'far away', t * 0.04, 1.0);

    // ── Gravitational field lines ──
    ctx.strokeStyle = 'rgba(255,100,0,0.07)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 16; i++) {
      const a = (i/16) * Math.PI*2;
      ctx.beginPath();
      for (let r = 38; r < Math.min(W, H)*0.6; r += 4) {
        const px = cx + Math.cos(a)*r, py = cy + Math.sin(a)*r*0.4;
        if (r === 38) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.stroke();
    }

    // Factor bar
    const barX = 12, barY = H - 30, barW = W - 24, barH = 12;
    ctx.fillStyle = 'rgba(255,255,255,0.05)';
    roundRect(ctx, barX, barY, barW, barH, 6); ctx.fill();
    const fillW = barW * factor;
    const grad = ctx.createLinearGradient(barX, 0, barX+fillW, 0);
    grad.addColorStop(0, '#ff5252'); grad.addColorStop(1, '#00e5ff');
    ctx.fillStyle = grad;
    roundRect(ctx, barX, barY, fillW, barH, 6); ctx.fill();
    ctx.fillStyle = '#fff'; ctx.font = '600 10px Nunito';
    ctx.fillText(`Twin A clock speed: ${(factor*100).toFixed(2)}% of Twin B   |   Gravity factor: ${factor.toFixed(4)}`, barX+6, barY+9);
  }

  function drawTwin(cx, cy, color, name, subtitle, clockAngle, factor) {
    // Body
    ctx.beginPath(); ctx.arc(cx, cy, 18, 0, Math.PI*2);
    const g = ctx.createRadialGradient(cx-5, cy-5, 1, cx, cy, 18);
    g.addColorStop(0, '#fff'); g.addColorStop(0.5, color); g.addColorStop(1, '#000');
    ctx.fillStyle = g; ctx.fill();
    ctx.strokeStyle = color; ctx.lineWidth = 2;
    ctx.shadowBlur = 12; ctx.shadowColor = color; ctx.stroke(); ctx.shadowBlur = 0;

    // Clock (floating above)
    drawSmallClock(ctx, cx, cy - 38, clockAngle, color);

    // Label
    ctx.fillStyle = color; ctx.font = '700 11px Nunito'; ctx.textAlign = 'center';
    ctx.fillText(name, cx, cy + 32);
    ctx.fillStyle = 'rgba(255,255,255,0.5)'; ctx.font = '600 9px Nunito';
    ctx.fillText(subtitle, cx, cy + 44); ctx.textAlign = 'left';
  }

  function drawSmallClock(ctx, cx, cy, angle, color) {
    const r = 14;
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2);
    ctx.fillStyle = '#010a14'; ctx.fill();
    ctx.strokeStyle = color; ctx.lineWidth = 1.5; ctx.stroke();
    // Hands
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(angle - Math.PI/2) * (r-4), cy + Math.sin(angle - Math.PI/2) * (r-4));
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5; ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(angle*6 - Math.PI/2) * (r-3), cy + Math.sin(angle*6 - Math.PI/2) * (r-3));
    ctx.strokeStyle = color; ctx.lineWidth = 1; ctx.stroke();
    ctx.beginPath(); ctx.arc(cx, cy, 2, 0, Math.PI*2);
    ctx.fillStyle = color; ctx.fill();
  }

  function roundRect(ctx, x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x+r,y); ctx.lineTo(x+w-r,y);
    ctx.quadraticCurveTo(x+w,y,x+w,y+r); ctx.lineTo(x+w,y+h-r);
    ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h); ctx.lineTo(x+r,y+h);
    ctx.quadraticCurveTo(x,y+h,x,y+h-r); ctx.lineTo(x,y+r);
    ctx.quadraticCurveTo(x,y,x+r,y); ctx.closePath();
  }

  function quiz(btn, correct) {
    if (quizDone) return; quizDone = true;
    const btns = btn.closest('.quiz-options').querySelectorAll('button');
    btns.forEach(b => { b.disabled = true; });
    const res = document.getElementById('quiz-bh-result');
    if (correct) {
      btn.classList.add('correct');
      res.className = 'quiz-result win';
      res.textContent = '✅ Correct! A singularity is where our current physics equations predict infinite density and zero volume — a point where gravity overwhelms all other forces. Real black holes have been photographed (M87*, Sagittarius A*).';
      GameEngine.addScore(10);
    } else {
      btn.classList.add('wrong');
      btns.forEach(b => { if (b.textContent.includes('infinite')) b.classList.add('correct'); });
      res.className = 'quiz-result lose';
      res.textContent = '❌ Not quite. A singularity is the point of infinite density at the center of a black hole — where spacetime curvature becomes infinite.';
    }
  }

  return { init, update, quiz };
})(); // ── BRANCHING UNIVERSES SIM ──
const BranchSim = (() => {
  let canvas, ctx, raf, t = 0;
  let branches = [];
  let quizDone = false;

  function init() {
    canvas = document.getElementById('branches-canvas');
    ctx = canvas.getContext('2d');
    canvas.width = Math.min(700, window.innerWidth - 48);
    canvas.height = 380;
    reset();
  }

  function reset() {
    branches = [{
      id: 0, parent: null,
      splitT: 0, splitX: canvas.width / 2,
      color: '#00e5ff', label: 'Universe Prime',
      alive: true, children: []
    }];
    document.getElementById('branch-count').textContent = 'Branches: 1';
    document.getElementById('branch-fact').textContent = 'Press "Trigger Quantum Event" to split the timeline!';
    cancelAnimationFrame(raf);
    t = 0;
    animate();
  }

  function addEvent() {
    const living = branches.filter(b => b.alive);
    if (living.length > 16) {
      document.getElementById('branch-fact').textContent = '🌌 Maximum branches reached! The multiverse is enormous — in theory, infinite splits occur every Planck time (~10⁻⁴³ seconds)!';
      return;
    }
    living.forEach(b => {
      const newId = branches.length;
      const splitX = b.splitX + (Math.random() - 0.5) * 80;
      const hue = Math.floor(Math.random() * 360);
      const child = {
        id: newId, parent: b.id,
        splitT: t, splitX: Math.max(40, Math.min(canvas.width - 40, splitX)),
        color: `hsl(${hue},85%,65%)`,
        label: `Branch ${newId}`, alive: true, children: []
      };
      b.children.push(newId);
      branches.push(child);
    });
    document.getElementById('branch-count').textContent = `Branches: ${branches.length}`;
    const facts = [
      '⚛️ Quantum event! A particle was measured — reality split into ALL possible outcomes simultaneously!',
      '🔀 Every split is equally real. You exist in BOTH branches — just different versions of you!',
      '🌌 Hugh Everett III proposed Many-Worlds in 1957. It removes randomness — all outcomes happen!',
      '🧪 The double-slit experiment shows particles going through both slits at once — evidence of superposition!',
      '♾️ If Many-Worlds is true, there are infinite copies of you making every possible choice right now!',
    ];
    document.getElementById('branch-fact').textContent = facts[Math.floor(Math.random() * facts.length)];
  }

  function animate() {
    t++;
    draw();
    raf = requestAnimationFrame(animate);
  }

  function draw() {
    if (!canvas) return;
    const W = canvas.width, H = canvas.height;
    ctx.clearRect(0, 0, W, H);

    // Grid
    ctx.strokeStyle = 'rgba(255,145,0,0.05)';
    ctx.lineWidth = 1;
    for (let x = 0; x < W; x += 50) { ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,H); ctx.stroke(); }
    for (let y = 0; y < H; y += 50) { ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke(); }

    const maxT = Math.max(t, 100);
    const tScale = (H - 40) / maxT;

    function tToY(tv) { return 20 + tv * tScale; }

    // Draw each branch
    branches.forEach(b => {
      const startY = tToY(b.splitT);
      const endY = tToY(Math.min(t, maxT));

      // Drift: branches slowly spread apart
      const age = t - b.splitT;
      const drift = (b.id % 2 === 0 ? 1 : -1) * Math.floor(b.id / 2) * 0.18;
      const curX = b.splitX + drift * age;

      // Draw line from split to now
      ctx.beginPath();
      ctx.moveTo(b.splitX, startY);
      // Wiggle slightly for quantum uncertainty
      for (let step = b.splitT; step < Math.min(t, maxT); step += 8) {
        const frac = (step - b.splitT) / Math.max(1, age);
        const wx = b.splitX + drift * (step - b.splitT) + Math.sin(step * 0.3 + b.id) * 2;
        ctx.lineTo(wx, tToY(step));
      }
      ctx.strokeStyle = b.color;
      ctx.lineWidth = 2.5;
      ctx.shadowBlur = 8; ctx.shadowColor = b.color;
      ctx.stroke(); ctx.shadowBlur = 0;

      // Current position dot
      const nowX = b.splitX + drift * age + Math.sin(t * 0.3 + b.id) * 2;
      const pulse = 0.5 + 0.5 * Math.sin(t * 0.1 + b.id);
      ctx.beginPath(); ctx.arc(nowX, endY, 8 + pulse * 3, 0, Math.PI * 2);
      ctx.fillStyle = b.color.replace(')', `,${0.2 * pulse})`).replace('hsl', 'hsla'); ctx.fill();
      ctx.beginPath(); ctx.arc(nowX, endY, 5, 0, Math.PI * 2);
      ctx.fillStyle = b.color; ctx.fill();

      // Label
      ctx.fillStyle = b.color; ctx.font = '600 9px Nunito';
      ctx.textAlign = 'center'; ctx.fillText(b.label, nowX, endY - 14);
      ctx.textAlign = 'left';

      // Split point marker
      if (b.parent !== null) {
        ctx.beginPath(); ctx.arc(b.splitX, startY, 5, 0, Math.PI * 2);
        ctx.fillStyle = '#fff'; ctx.fill();
        ctx.strokeStyle = b.color; ctx.lineWidth = 2; ctx.stroke();
        ctx.fillStyle = 'rgba(255,255,255,0.5)'; ctx.font = '600 8px Nunito';
        ctx.textAlign = 'center'; ctx.fillText('SPLIT', b.splitX, startY - 8); ctx.textAlign = 'left';
      }
    });

    // Time arrow
    ctx.strokeStyle = 'rgba(255,145,0,0.6)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(16, 20); ctx.lineTo(16, H - 20); ctx.stroke();
    ctx.fillStyle = 'rgba(255,145,0,0.8)'; ctx.font = '700 10px Nunito';
    ctx.save(); ctx.translate(10, H/2); ctx.rotate(-Math.PI/2);
    ctx.textAlign = 'center'; ctx.fillText('TIME →', 0, 0); ctx.restore();
    // Arrow head
    ctx.beginPath(); ctx.moveTo(16, H-20); ctx.lineTo(10, H-30); ctx.lineTo(22, H-30); ctx.closePath();
    ctx.fillStyle = 'rgba(255,145,0,0.6)'; ctx.fill();
  }

  function quiz(btn, correct) {
    if (quizDone) return; quizDone = true;
    const btns = btn.closest('.quiz-options').querySelectorAll('button');
    btns.forEach(b => b.disabled = true);
    const res = document.getElementById('quiz-branch-result');
    if (correct) {
      btn.classList.add('correct');
      res.className = 'quiz-result win';
      res.textContent = '✅ Correct! In Many-Worlds, the timeline BRANCHES. You still exist in your original branch. The "grandfather paradox" is solved — you can\'t erase yourself, only create a new branch where you don\'t exist!';
      GameEngine.addScore(10);
    } else {
      btn.classList.add('wrong');
      btns.forEach(b => { if (b.textContent.includes('new branch')) b.classList.add('correct'); });
      res.className = 'quiz-result lose';
      res.textContent = '❌ In Many-Worlds, going back creates a BRANCH. Your original timeline still exists. This elegantly solves the grandfather paradox!';
    }
  }

  return { init, reset, addEvent, quiz };
})();

