const glow = state === “running” ? `0 0 12px ${colors.running}` : state === “done” ? `0 0 8px ${colors.done}` : “none”;
return (
<span style={{
display: “inline-block”, width: 10, height: 10, borderRadius: “50%”,
background: colors[state] || “#333”, boxShadow: glow,
animation: state === “running” ? “pulse 0.8s ease-in-out infinite alternate” : “none”,
flexShrink: 0,
}} />
);
}

function KernelCard({ kernel, state, output, active }) {
const isRunning = state === “running”;
const isDone = state === “done”;
